import numpy as np

try:
    from scipy.linalg.lapack import get_lapack_funcs as _get_lapack_funcs
except Exception:  # scipy not available at runtime
    _get_lapack_funcs = None


def _eig_numpy(A):
    eigenvalues, eigenvectors = np.linalg.eig(A)
    idx = np.argmax(np.abs(eigenvalues))
    return eigenvalues[idx], eigenvectors[:, idx]


def find_dominant_eigenvalue_and_eigenvector(A: np.ndarray):
    """
    Find the dominant eigenvalue and eigenvector of a general real square matrix.

    Args:
        A: Real-valued square matrix (accepts numpy arrays) up to size 10x10,
        dtype np.float64.

    Returns:
        eigenvalue: Dominant eigenvalue (numpy scalar, potentially complex)
        eigenvector: Corresponding eigenvector (np.ndarray, potentially complex)
    """
    if _get_lapack_funcs is None:
        return _eig_numpy(A)

    A = np.asarray(A)
    try:
        (geev,) = _get_lapack_funcs(("geev",), (A,))
        res = geev(A, compute_vl=0, compute_vr=1)
        # For real geev: (wr, wi, vl, vr, info)
        # For complex geev: (w, vl, vr, info)
        if len(res) == 5:
            wr, wi, _vl, vr, info = res
            if info != 0:
                return _eig_numpy(A)
            mag = wr * wr + wi * wi
            i = int(np.argmax(mag))
            wii = wi[i]
            if wii == 0.0:
                return np.complex128(wr[i]), vr[:, i].astype(np.complex128)
            if wii > 0.0:
                return np.complex128(complex(wr[i], wii)), vr[:, i] + 1j * vr[:, i + 1]
            return np.complex128(complex(wr[i], wii)), vr[:, i - 1] - 1j * vr[:, i]
        else:
            w, _vl, vr, info = res
            if info != 0:
                return _eig_numpy(A)
            i = int(np.argmax(np.abs(w)))
            return w[i], vr[:, i]
    except Exception:
        return _eig_numpy(A)
